# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('fume','/fjuːm/','烟气；刺鼻气体；发怒','烟气往外冒，怒气也像压不住地往外冒。','名词经古法语 fum 来自拉丁 fumus 烟；动词经法语 fumer 来自拉丁 fumare 冒烟、熏。发怒是英语里的比喻扩展。',[['拉丁 fumus／fumare → 古法语 fum／fumer','烟气；冒烟或熏'],['英语 fume','烟气；冒气；比喻生气、恼火']],'说汽车尾气或刺激性气体时常用复数 fumes，如 exhaust fumes。说人时，She was fuming 是她气得不行；可以想成气得冒烟，但不要求她真的大喊大叫。','exhaust fumes；toxic fumes；fume at a decision；fume over a delay；be fuming。','smoke 通常让人想到可见的燃烧烟雾；fumes 强调散出的气体或烟气，常有难闻、刺激的感觉，不一定看得见。',('Exhaust fumes drifted into the open window.','汽车尾气飘进了敞开的窗户。'),('He was still fuming over the cancelled meeting.','他还在为会议取消的事生气。'),sources=['https://www.etymonline.com/word/fume','https://en.wiktionary.org/wiki/fume#English']),
E('perfume','名词：英 /ˈpɜːfjuːm/，美 /ˈpɜːrfjuːm/；动词 /pəˈfjuːm/（美 /pərˈfjuːm/）','香水；香气；使充满香味','从带香味的烟，走到瓶里的香水和空气中的香气。','借自法语 parfum／parfumer，向上联系罗曼语言的 perfumar 等形式；构词材料最终是拉丁 per- 贯穿、充分和 fumare 冒烟、熏。',[['拉丁 per- + fumare → 罗曼语言 perfumar 等形式','充分地熏，使带香气'],['法语 parfum／parfumer → 英语 perfume','香气、香水；使带香味']],'wear perfume 是用香水，the perfume of flowers 是花香。动词 perfume the room 是让房间充满香味。它的烟来自历史上的熏香，不表示现代香水一定要烧起来；也不能拆成英语 pure 加 fume。','wear perfume；a bottle of perfume；the perfume of roses；flowers perfume the air。','perfume 多指香水或令人愉悦的香气；fumes 现代常说刺激或有害气体。scent 范围更广，可以说气味痕迹。',('She wears a light floral perfume.','她用一种清淡的花香香水。'),('Fresh flowers perfumed the room.','鲜花让房间里弥漫着香气。'),sources=['https://www.etymonline.com/word/perfume','https://en.wiktionary.org/wiki/perfume#English']),
E('perfumer','英 /pəˈfjuːmə/；美 /pərˈfjuːmər/','调香师；香水制造者或经营者','把不同气味调成一种香水的人。','可分析为 perfume + 表示人的 -er，形成时也可能受到法语 parfumeur 影响。',[['英语 perfume；法语有 parfumeur','香水与制作香水的职业名称'],['英语 perfumer','调制、制造或销售香水的人']],'现代介绍香水创作时，perfumer 往往就是调香师：像作曲家组合声音一样，组合不同香气。某些语境也指生产或销售香水的人、商家，具体看上下文。','a master perfumer；a French perfumer；work as a perfumer。','perfumer 是人或经营者；perfume 是产品或香气。不是所有卖香水的店员都会被日常称为专业调香师。',('The perfumer tested several versions of the fragrance.','调香师测试了这款香水的几个版本。'),('She trained as a perfumer before starting her own brand.','她在创立自己的品牌前接受过调香师训练。'),sources=['https://en.wiktionary.org/wiki/perfumer#English']),
E('perfumery','英 /pəˈfjuːməri/；美 /pərˈfjuːməri/','香水制作业；调香工艺；香水店','把镜头从一瓶香水拉远，看到制作香水的手艺、行业或店铺。','以 perfume／perfumer 为基础形成，-ery 常表示某种行业、活动或营业场所；也可按 perfumer + -y 分析。',[['英语 perfume／perfumer','香水；制作和经营香水的人'],['英语 perfumery','调香工艺、香水行业；香水店']],'study perfumery 是学习调香，work in perfumery 是从事香水行业；a perfumery 则可以是一家香水店或作坊。抽象的工艺、行业用法与具体的店铺用法要看冠词和句子。','the art of perfumery；modern perfumery；a small perfumery。','perfumer 是从业者，perfumery 是工艺、行业或场所。perfume 才是最常用的香水产品名称。',('She is studying the art of perfumery.','她正在学习调香工艺。'),('We visited a small perfumery in the old town.','我们参观了老城区的一家小香水作坊。'),sources=['https://www.dictionary.com/browse/perfumery','https://en.wiktionary.org/wiki/perfumery#English']),
E('fumigation','/ˌfjuːmɪˈɡeɪʃən/','熏蒸处理；熏蒸除害','让气体进入空间或物品内部，完成熏蒸处理。','来自拉丁 fumigatio，源于 fumigare 用烟熏；其材料是 fumus 烟和 agere 做、使运动。经法语或拉丁借入英语，早期也用于熏香活动。',[['拉丁 fumus + agere → fumigare → fumigatio','烟 + 使发生 → 熏 → 熏的过程'],['英语 fumigation','熏香、熏治；现代常指熏蒸除害处理']],'如今常在仓库、建筑、货物处理等语境见到。重点是用烟气或气态药剂进行处理，不是把地面扫干净。这个英语名词比 fumigate 更早出现，不能把真实历史简单写成英语动词后加 -ion。','fumigation treatment；a fumigation service；close a building for fumigation。','cleaning 泛指清洁；fumigation 是一种特定处理方式。fumigation 是过程名称，fumigate 是实施动作。',('The warehouse was closed during fumigation.','仓库在熏蒸处理期间关闭。'),('The company arranged professional fumigation for the infested building.','公司为那栋遭虫害的建筑安排了专业熏蒸处理。'),sources=['https://www.etymonline.com/word/fumigation','https://en.wiktionary.org/wiki/fumigation#English','https://dictionary.cambridge.org/us/dictionary/english/fumigate']),
E('fumigate','/ˈfjuːmɪɡeɪt/','用烟气熏；熏蒸除害','对一个地方或一批物品实施熏蒸处理。','通常解释为从较早的英语 fumigation 逆构出动词；其最终来源仍是拉丁 fumigare 用烟熏。',[['拉丁 fumigatio → 英语 fumigation','熏的过程、熏蒸处理'],['英语 fumigate','从已有名词形成动词，表示进行熏蒸']],'fumigate the warehouse 是熏蒸仓库；have the house fumigated 是请人给房子做熏蒸处理。现代常与杀虫、除害相关，历史上也有用香气熏的意思，不要将所有旧句都理解成现代杀虫工程。','fumigate a building；fumigate stored grain；have a room fumigated。','fumigate 说做这件事；fumigation 说这项处理。现代构词看着像动词加后缀，但词的出现顺序恰好相反。',('The specialists were hired to fumigate the warehouse.','这些专业人员受雇给仓库做熏蒸处理。'),('The owners had the empty building fumigated before reopening it.','业主在重新开放空置建筑前，请人进行了熏蒸处理。'),sources=['https://www.etymonline.com/word/fumigate','https://dictionary.cambridge.org/us/dictionary/english/fumigate'])]
ROOT=dict(id='C0455',meaning='烟；气体；熏',core='FUM = SMOKE',image='烟气散开：可能是刺鼻气体，也可能是早期熏香；人的怒气也能被比作冒烟。',intro='拉丁 fumus 是烟，fumare 是冒烟或熏。fume、perfume 与 fumigation 各走一条借入路线，现代意思已经明显分开。',forms='fumus／fumare → 法语 fum／fumer → fume；per- + fumare → 罗曼语言、法语 → perfume；fumus + agere → fumigare → fumigatio → fumigation → 英语逆构 fumigate。',branches=[['烟气与怒气','fume'],['香气与调香','perfume；perfumer；perfumery'],['熏蒸过程和动作','fumigation；fumigate']],contrasts='同一个烟气意象能走向不同评价：perfume 通常令人愉悦，fumes 常令人不舒服。不能用今天的气味好坏倒推它们毫无关系。',practice='She loved the perfume of the flowers but disliked the exhaust fumes outside.\n\n她喜欢花的香气，却不喜欢外面的汽车尾气。',words=[x['word'] for x in W],exclude={})
